import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { vec3, uv, mix } from 'three/tsl';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
    const { Group, Mesh, PlaneGeometry, Vector3, Color } = ctx.THREE;

    // Root container (position/rotation handled by adapter)
    const root = new Group();

    // ---------- Rail (background panel) ----------
    const railWidth = 3.6;
    const railHeight = 0.5;
    const railGeom = new PlaneGeometry(railWidth, railHeight);
    const topColor = new Color('#1b1b23');
    const bottomColor = new Color('#101015');

    const railMat = new MeshStandardNodeMaterial({
        metalness: 0.5,
        roughness: 0.55,
        clearcoat: 0.2,
        // Gradient albedo from top to bottom
        colorNode: mix(
            vec3(topColor.r, topColor.g, topColor.b),
            vec3(bottomColor.r, bottomColor.g, bottomColor.b),
            uv().y
        )
    });
    const railMesh = new Mesh(railGeom, railMat);
    railMesh.position.z = 0.15; // floats above shadow
    root.add(railMesh);

    // ---------- Contact shadow plane ----------
    const shadowMat = new MeshBasicNodeMaterial({
        colorNode: vec3(0, 0, 0),
        opacityNode: 0.35,
        transparent: true
    });
    const shadowMesh = new Mesh(railGeom, shadowMat);
    shadowMesh.position.z = 0.0; // directly under rail
    root.add(shadowMesh);

    // ---------- Navigation entries ----------
    const entriesSpec = [
        { label: 'HOME', role: 'nav-active' },
        { label: 'FEATURES', role: 'nav-item' },
        { label: 'COLLECTION', role: 'nav-item' },
        { label: 'PRICING', role: 'nav-item' },
        { label: 'JOURNAL', role: 'nav-item' }
    ];

    const entrySpacing = 0.68;
    const startX = -entrySpacing * (entriesSpec.length - 1) / 2;
    const inactiveColorHex = '#a6adba';
    const activeColorHex = '#e8ecf2';
    const hoverColorHex = '#e8ecf2';
    const underlineColorHex = '#ff2a38';

    const entryGroups = [];
    const cleanupArray = [];

    const underlineGeom = new PlaneGeometry(0.28, 0.025);
    const underlineMat = new MeshStandardNodeMaterial({
        color: new Color(underlineColorHex),
        emissive: new Color(underlineColorHex),
        emissiveIntensity: 1.8,
        metalness: 0,
        roughness: 1,
        transparent: true
    });
    const underlineMesh = new Mesh(underlineGeom, underlineMat);
    underlineMesh.position.y = -0.06; // 0.06 below baseline
    underlineMesh.position.z = 0.151; // just above rail surface
    root.add(underlineMesh);

    entriesSpec.forEach((spec, idx) => {
        const isActive = spec.role === 'nav-active';
        const entryGroup = new Group();
        const cx = startX + idx * entrySpacing;
        entryGroup.position.set(cx, 0, 0);
        entryGroup.userData.name = spec.label;

        const txt = ctx.fontAtlas.createText(spec.label, {
            fontSize: 13,
            color: isActive ? activeColorHex : inactiveColorHex,
            align: 'center',
            letterSpacing: 0.08
        });
        // Center text vertically
        txt.position.y = 0;
        entryGroup.add(txt);

        // Store for interaction handling
        entryGroups.push({
            name: spec.label,
            group: entryGroup,
            textObj: txt,
            isActive,
            baseScale: new Vector3(1, 1, 1)
        });

        root.add(entryGroup);
    });

    // ---------- Setup underline initial position ----------
    const activeEntry = entryGroups.find(e => e.isActive) || entryGroups[0];
    underlineMesh.position.x = activeEntry.group.position.x;

    // ---------- Interaction Handlers ----------
    const handlers = {};

    handlers.hoverEnter = (name) => {
        const entry = entryGroups.find(e => e.name === name);
        if (!entry || entry.isActive) return;
        gsap.to({}, {
            duration: 0.16,
            onComplete: () => setTextColor(entry.textObj, hoverColorHex)
        });
    };

    handlers.hoverLeave = (name) => {
        const entry = entryGroups.find(e => e.name === name);
        if (!entry || entry.isActive) return;
        gsap.to({}, {
            duration: 0.16,
            onComplete: () => setTextColor(entry.textObj, inactiveColorHex)
        });
    };

    handlers.press = (name) => {
        const entry = entryGroups.find(e => e.name === name);
        if (!entry) return;
        gsap.to(entry.group.scale, {
            x: 0.97,
            y: 0.97,
            z: 0.97,
            duration: 0.12,
            ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
        });
        gsap.to(entry.group.position, {
            z: -0.03,
            duration: 0.12,
            ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
        });
    };

    handlers.release = (name) => {
        const entry = entryGroups.find(e => e.name === name);
        if (!entry) return;
        gsap.to(entry.group.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.12,
            ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
        });
        gsap.to(entry.group.position, {
            z: 0,
            duration: 0.12,
            ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
        });
    };

    handlers.click = (name) => {
        // Emit navigation based on label lowercased
        const target = `hub-${name.toLowerCase()}`;
        ctx.emit('navigate', { to: target });
        setActive(name);
    };

    function setActive(name) {
        const newActive = entryGroups.find(e => e.name === name);
        if (!newActive) return;
        entryGroups.forEach(e => {
            if (e === newActive) {
                e.isActive = true;
                setTextColor(e.textObj, activeColorHex);
            } else if (e.isActive) {
                e.isActive = false;
                setTextColor(e.textObj, inactiveColorHex);
            }
        });
        // Animate underline movement with overshoot
        const tl = gsap.timeline();
        tl.to(underlineMesh.position, {
            x: newActive.group.position.x,
            duration: 0.26,
            ease: 'cubic-bezier(0.165,0.84,0.44,1)'
        });
        cleanupArray.push(tl);
    }

    // ---------- Mount animation ----------
    const mountTL = gsap.timeline();
    mountTL.from(root.position, {
        y: 0.4,
        duration: 0.7,
        ease: 'cubic-bezier(0.215,0.61,0.355,1)'
    });
    cleanupArray.push(mountTL);

    // ---------- Utility ----------
    function setTextColor(textObj, hex) {
        const col = new Color(hex);
        textObj.traverse((c) => {
            if (c.isMesh && c.material && c.material.color) {
                c.material.color.set(col);
                c.material.needsUpdate = true;
            }
        });
    }

    // ---------- Cleanup ----------
    root.userData.handlers = handlers;
    root.userData.cleanup = () => {
        cleanupArray.forEach(tl => {
            if (tl && tl.kill) tl.kill();
        });
        // Dispose materials & geometries
        railMesh.geometry.dispose();
        railMat.dispose();
        shadowMesh.geometry.dispose();
        shadowMat.dispose();
        underlineMesh.geometry.dispose();
        underlineMat.dispose();
        entryGroups.forEach(e => {
            e.group.traverse((c) => {
                if (c.isMesh) {
                    if (c.geometry) c.geometry.dispose();
                    if (c.material) c.material.dispose();
                }
            });
        });
    };

    return root;
}
